-- ===== runtime tables & seeds =====
-- Runtime tables + seeds required on top of the generated schema

CREATE TABLE IF NOT EXISTS `installer` (
  `id` INT(11) NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `installer_flag` INT(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB;

INSERT INTO `installer` (`installer_flag`) SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM `installer`);

CREATE TABLE IF NOT EXISTS `tbl_sessions` (
  `id` varchar(128) NOT NULL,
  `ip_address` varchar(45) NOT NULL,
  `timestamp` int(10) unsigned NOT NULL DEFAULT 0,
  `data` blob NOT NULL,
  KEY `ci_sessions_timestamp` (`timestamp`)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `tbl_countries` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `value` TEXT NULL
) ENGINE=InnoDB;

INSERT INTO `tbl_countries` (`value`) SELECT v.c FROM (
  SELECT 'United States' c UNION SELECT 'United Kingdom' UNION SELECT 'Canada' UNION SELECT 'Australia'
  UNION SELECT 'Germany' UNION SELECT 'France' UNION SELECT 'India' UNION SELECT 'Pakistan'
  UNION SELECT 'Bangladesh' UNION SELECT 'Japan' UNION SELECT 'Brazil' UNION SELECT 'United Arab Emirates'
) v WHERE NOT EXISTS (SELECT 1 FROM `tbl_countries`);

INSERT INTO `tbl_currencies` (`name`,`code`,`symbol`) SELECT 'US Dollar','USD','$'
  WHERE NOT EXISTS (SELECT 1 FROM `tbl_currencies` WHERE `code`='USD');
