-- framework-critical config keys must never be shadowed by empty DB rows
DELETE FROM `tbl_config` WHERE `config_key` IN (
  'encryption_key','base_url','index_page','uri_protocol','subclass_prefix','enable_hooks',
  'composer_autoload','log_threshold','log_path','log_date_format','cache_path','sess_driver',
  'sess_save_path','sess_table_name','sess_use_database','sess_cookie_name','cookie_prefix',
  'cookie_domain','cookie_path','cookie_secure','csrf_protection','global_xss_filtering',
  'rewrite_short_tags','proxy_ips'
);

